  await page.unrouteAll();
  await page.route('**/*', async route => {
    await route.continue({ headers: { ...route.request().headers(), 'baggage': 'sd-routing-key=5tp1mjqypbb7d', 'tracestate': 'sd-routing-key=5tp1mjqypbb7d' } });
  });
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  const opts = await page.$$eval('select option', os => os.map(o => `${o.value}|${o.textContent}`));
  return { len: (await page.content()).length, opts };
}

