async (page) => {
  const errs = []; page.on('pageerror', e => errs.push(String(e)));
  const sels = page.locator('select');
  await sels.nth(0).selectOption('1');
  await sels.nth(1).selectOption('123');
  await page.getByRole('button', {name: 'Request Ride'}).click();
  await page.getByRole('button', {name: 'Show Logs'}).click();
  await page.waitForTimeout(8000);
  const body = await page.innerText('body');
  await page.screenshot({path: '/tmp/ui.png'});
  return { errs, len: (await page.content()).length, body: body.slice(0, 1500) };
}

