async (page) => {
  const reqs = [];
  page.on('requestfailed', r => reqs.push('FAILED ' + r.url()));
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  const sels = page.locator('select');
  await sels.nth(0).selectOption('1');
  await sels.nth(1).selectOption('567');
  await page.getByRole('button', {name: 'Request Ride'}).click();
  await page.getByRole('button', {name: 'Show Logs'}).click();
  await page.waitForTimeout(15000);
  const body = await page.innerText('body');
  return { reqs, body: body.slice(body.indexOf('Logs'), body.indexOf('Logs') + 1200) };
}

